<script setup lang="ts">
import { computed, ref, watch } from 'vue';import { useRoute } from 'vue-router';import { ElMessage, ElMessageBox } from 'element-plus';import { api, date, labels } from '../api';
function clone(value:any){return JSON.parse(JSON.stringify(value));}
const route=useRoute();const kind=computed(()=>route.params.kind==='rules'?'rules':'public');const config=ref<any>(null);const version=ref('');const draft=ref('');const loading=ref(false);const busy=ref(false);const error=ref('');const group=ref('categories');const dialog=ref(false);const entry=ref<any>({});const original=ref('');const historyOpen=ref(false);const versions=ref<any[]>([]);const terms=ref('');
const groups:Record<string,string>={categories:'类目与字段',campuses:'校区',colleges:'学院',majors:'专业',courses:'课程',tags:'标签',conditions:'成色',noteLevels:'笔记等级',rentalRestrictions:'租用禁限品类'};
async function load(){loading.value=true;error.value='';draft.value='';try{const r=await api('/settings?kind='+kind.value);config.value=clone(r.content);version.value=r.version;terms.value=(r.content.prohibitedTerms||[]).join('\n');}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
watch(kind,load,{immediate:true});
function edit(row?:any){original.value=row?.code||'';entry.value=row?clone(row):{code:'',name:'',active:true,parent:'',description:'',icon:'',fields:[]};dialog.value=true;}
function saveEntry(){if(!entry.value.code.trim()||!entry.value.name.trim())return ElMessage.warning('请填写编码和名称');const rows=config.value[group.value];if(rows.some((x:any)=>x.code===entry.value.code&&x.code!==original.value))return ElMessage.warning('编码已存在');const index=rows.findIndex((x:any)=>x.code===original.value);if(index>=0)rows[index]=clone(entry.value);else rows.push(clone(entry.value));draft.value='';dialog.value=false;}
function addField(){entry.value.fields.push({code:'',name:'',type:'text',required:false,options:[]});}
async function saveDraft(){busy.value=true;try{if(kind.value==='rules')config.value.prohibitedTerms=terms.value.split('\n').map(s=>s.trim()).filter(Boolean);const r=await api('/action',{op:'config.save',kind:kind.value,content:config.value});draft.value=r._id;ElMessage.success('草稿已保存，尚未影响用户端');}catch(e){ElMessage.error((e as Error).message);}finally{busy.value=false;}}
async function publish(target:string){try{const {value}=await ElMessageBox.prompt('发布后将影响新提交的业务。历史记录保留原值。请填写发布或回滚原因。','确认发布配置',{inputType:'textarea',inputValidator:v=>!!v?.trim()||'请填写原因',confirmButtonText:'确认发布',cancelButtonText:'取消'});busy.value=true;await api('/action',{op:'config.publish',id:target,reason:value,confirm:true});ElMessage.success('配置已发布');historyOpen.value=false;await load();}catch(e){if(e instanceof Error)ElMessage.error(e.message);}finally{busy.value=false;}}
async function history(){try{const r=await api('/list?entity='+ (kind.value==='rules'?'rules':'configs'));versions.value=r.list;historyOpen.value=true;}catch(e){ElMessage.error((e as Error).message);}}
</script>
<template><div class="page-intro"><div><span class="eyebrow">CONFIGURATION</span><h1>{{ kind==='rules'?'风控规则':'类目与字典' }}</h1><p>{{ kind==='rules'?'以明确阈值识别交易风险，变更须经过发布确认。':'统一维护小程序使用的目录、字段和业务选项。' }}</p></div><div class="button-row"><el-button @click="history">历史版本</el-button><el-button :loading="busy" @click="saveDraft">保存草稿</el-button><el-button type="primary" :disabled="!draft" :loading="busy" @click="publish(draft)">发布草稿</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-alert v-if="draft" title="草稿已保存。继续编辑后，请再次保存再发布。" type="warning" :closable="false" class="mb"/><div v-loading="loading" style="min-height:300px"><template v-if="config"><div class="config-version">当前版本 <code>{{ version }}</code><span>配置不会自动发布</span></div><section v-if="kind==='public'" class="panel"><el-tabs v-model="group"><el-tab-pane v-for="(label,key) in groups" :key="key" :label="label" :name="key"/></el-tabs><div class="panel-heading"><h2>{{ groups[group] }}</h2><el-button type="primary" plain @click="edit()">新增条目</el-button></div><el-table :data="config[group]" stripe empty-text="尚未配置，可新增条目"><el-table-column prop="code" label="稳定编码" min-width="150"/><el-table-column prop="name" label="显示名称" min-width="150"/><el-table-column prop="parent" label="父级编码" min-width="130"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{ row.active?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column prop="description" label="说明" min-width="180" show-overflow-tooltip/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button></template></el-table-column></el-table><el-divider/><el-form label-position="top"><el-form-item label="关键页面交易安全提示"><el-input v-model="config.safetyTip" type="textarea" :rows="3" maxlength="500" show-word-limit @input="draft=''"/></el-form-item></el-form><p class="muted">被历史记录引用的编码请停用，保留显示名称。图书四级笔记等级必须保留。</p></section><section v-else class="panel rules-panel"><el-form label-position="top" @change="draft='' "><div class="rule-grid"><el-form-item label="每用户每小时最多报价次数"><el-input-number v-model="config.offerPerHour" :min="1" :max="10000" @change="draft=''"/></el-form-item><el-form-item label="每用户每分钟最多消息数"><el-input-number v-model="config.messagePerMinute" :min="1" :max="10000" @change="draft=''"/></el-form-item><el-form-item label="每用户每小时最多举报数"><el-input-number v-model="config.reportPerHour" :min="1" :max="10000" @change="draft=''"/></el-form-item><el-form-item label="报价修改最短间隔（秒，至少300）"><el-input-number v-model="config.priceChangeSeconds" :min="300" :max="86400" @change="draft=''"/></el-form-item><el-form-item label="竞价相对期望价的低价比例"><el-input-number v-model="config.lowPriceRatio" :min="0.01" :max="0.99" :step="0.05" :precision="2" @change="draft=''"/></el-form-item><el-form-item label="异常低价处理"><el-select v-model="config.action" @change="draft=''"><el-option value="review" label="进入人工复核"/><el-option value="block" label="直接拦截"/></el-select></el-form-item></div><el-divider/><el-form-item label="各类目低价阈值（元；0表示不使用绝对低价阈值）"><div class="rule-grid"><label v-for="cat in ['book','digital','life','stationery','sports','clothes','other']" :key="cat">{{ cat }}<el-input-number :model-value="config.lowPriceByCategory[cat]||0" :min="0" :precision="2" @change="(v:number|undefined)=>{config.lowPriceByCategory[cat]=v||0;draft=''}"/></label></div></el-form-item><el-form-item label="禁止内容词条（每行一条，命中后拒绝）"><el-input v-model="terms" type="textarea" :rows="6" @input="draft=''"/></el-form-item></el-form><el-alert title="低价仅是风险信号；不存在有效期望价时不作比例判断。配置发布和人工处理均记录审计。" type="info" :closable="false"/></section></template></div>
<el-dialog v-model="dialog" :title="original?'编辑条目':'新增条目'" width="min(900px, 95vw)"><el-form label-position="top"><div class="rule-grid"><el-form-item label="稳定编码"><el-input v-model="entry.code" :disabled="!!original"/></el-form-item><el-form-item label="显示名称"><el-input v-model="entry.name" maxlength="100"/></el-form-item><el-form-item label="父级编码"><el-select v-model="entry.parent" clearable filterable><el-option v-for="x in config[group].filter((v:any)=>v.code!==entry.code)" :key="x.code" :value="x.code" :label="x.name"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="entry.active"/></el-form-item></div><el-form-item label="说明"><el-input v-model="entry.description" type="textarea" maxlength="500"/></el-form-item><template v-if="group==='categories'"><el-form-item label="类目图标（文字或 Emoji）"><el-input v-model="entry.icon" maxlength="10"/></el-form-item><div class="panel-heading"><strong>类目扩展字段</strong><el-button @click="addField">添加字段</el-button></div><div v-for="(f,i) in entry.fields" :key="i" class="field-editor"><el-input v-model="f.code" placeholder="字段编码，如 brand"/><el-input v-model="f.name" placeholder="显示名称"/><el-select v-model="f.type"><el-option value="text" label="文本"/><el-option value="number" label="数字"/><el-option value="enum" label="枚举"/></el-select><el-checkbox v-model="f.required">必填</el-checkbox><el-button type="danger" link @click="entry.fields.splice(i,1)">移除</el-button><el-input v-if="f.type==='enum'" :model-value="f.options.join('，')" placeholder="选项，用逗号分隔" @input="(v:string)=>f.options=v.split(/[,，]/).map(x=>x.trim()).filter(Boolean)"/></div></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveEntry">应用到本地草稿</el-button></template></el-dialog><el-drawer v-model="historyOpen" title="配置历史版本" size="min(700px,95vw)"><el-table :data="versions"><el-table-column prop="_id" label="版本" min-width="180"/><el-table-column label="状态"><template #default="{row}">{{ labels[row.state]||row.state }}</template></el-table-column><el-table-column label="时间" min-width="170"><template #default="{row}">{{ date(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="publish(row._id)">发布此版本</el-button></template></el-table-column></el-table></el-drawer></template>
